import { z } from 'zod'

// Every environment-specific value is declared here — the config contract.
const schema = z.object({
  NODE_ENV: z.enum(['development', 'staging', 'production']),
  PORT: z.coerce.number().default(3000),
  // Secret: injected at runtime from the secret store, never a default.
  DATABASE_URL: z.string().url(),
  STRIPE_SECRET_KEY: z.string().startsWith('sk_'),
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
})

const parsed = schema.safeParse(process.env)

if (!parsed.success) {
  // Fail fast, fail loud — at boot, not mid-request in production.
  console.error('Invalid environment config:', parsed.error.flatten().fieldErrors)
  process.exit(1)
}

// Frozen: config is read-only after boot. No secret is ever logged.
export const config = Object.freeze(parsed.data)

