infrastructure-as-code.code:
variable "replicas"   { type = number, default = 3 }
variable "image_tag"  { type = string }

resource "kubernetes_deployment" "payments" {
  metadata { name = "payments", namespace = "prod" }
  spec {
    replicas = var.replicas
    selector { match_labels = { app = "payments" } }
    template {
      metadata { labels = { app = "payments" } }
      spec {
        container {
          name  = "payments"
          image = "registry.internal/payments:${var.image_tag}"
          resources { limits = { cpu = "500m", memory = "512Mi" } }
          readiness_probe { http_get { path = "/healthz", port = 8080 } }
        }
      }
    }
  }
}

resource "kubernetes_horizontal_pod_autoscaler_v2" "payments" {
  metadata { name = "payments", namespace = "prod" }
  spec {
    min_replicas = var.replicas
    max_replicas = 12
    scale_target_ref { kind = "Deployment", name = "payments" }
  }
}
# terraform plan -> 0 to add, 0 to change, 0 to destroy  (no drift)

